messages.content:
  1→/**
  2→ * Fetch one skill resource's raw bytes from the bridge, for saving to a file.
  3→ *
  4→ * The subpath matters. The bridge has two file reads:
  5→ *
  6→ *   files/read      always answers with a JSON envelope — a body meant to be
  7→ *                   parsed, not written to disk. `curl -o` does not change
  8→ *                   this (that flag is the client's; the bridge routes on the
  9→ *                   subpath), so saving its response leaves a JSON file where
 10→ *                   a script should be.
 11→ *   files/download  answers with the resource's raw bytes, which is what a
 12→ *                   caller that writes a file wants. This is the one used here.
 13→ *
 14→ * Two shapes come back on `files/download`, and both are decoded for the
 15→ * caller:
 16→ *
 17→ *   - raw bytes, on the ordinary success path;
 18→ *   - a JSON envelope, on failure (code !== 0, thrown), and — as the bridge
 19→ *     stands today — on **empty** content, because that branch treats "" as
 20→ *     absent (`!parsed.data?.content`) and returns the whole envelope. An
 21→ *     empty resource is a legal resource, so the envelope's empty `content`
 22→ *     is decoded to a zero-byte Buffer rather than reported as an error. Only
 23→ *     a missing or non-string `content` field is treated as an anomaly.
 24→ *
 25→ * A malformed upload answer must not be silently swallowed: when the bridge
 26→ * spells out a `message`, the thrown Error carries it.
 27→ *
 28→ * Tracking value for the team note this follows: bt-pvxahxcppk3.
 29→ *
 30→ * Usage:
 31→ *   const bytes = await fetchResource({
 32→ *     skillId: "skl-…", path: "scripts/run.sh",
 33→ *     bridgeBase: "http://127.0.0.1:8096/skill-bridge/v3/skill",
 34→ *   });
 35→ *   writeFileSync("run.sh", bytes);
 36→ */
 37→
 38→/** The subpath that serves raw bytes (not the JSON-envelope `files/read`). */
 39→const DOWNLOAD_SUBPATH = "files/download";
 40→
 41→/**
 42→ * Decode the response body to bytes, accepting the shapes an HTTP stub may
 43→ * return: a real Response (or anything with arrayBuffer/text/json), a Buffer,
 44→ * or the already-parsed body.
 45→ *
 46→ * @param {unknown} res
 47→ * @returns {Promise<Buffer>}
 48→ */
 49→async function readBytes(res) {
 50→  if (Buffer.isBuffer(res)) return res;
 51→  if (res instanceof Uint8Array) return Buffer.from(res);
 52→  if (typeof res === "string") return Buffer.from(res, "utf8");
 53→  if (res && typeof res === "object") {
 54→    if (typeof res.arrayBuffer === "function") return Buffer.from(await res.arrayBuffer());
 55→    if (typeof res.text === "function") return Buffer.from(await res.text(), "utf8");
 56→    if (typeof res.json === "function") return Buffer.from(JSON.stringify(await res.json()), "utf8");
 57→    // A stub may hand back the parsed envelope directly.
 58→    return Buffer.from(JSON.stringify(res), "utf8");
 59→  }
 60→  throw new Error("fetchResource: response has no readable body");
 61→}
 62→
 63→/**
 64→ * The bridge's envelope, if this body is one. The discriminant is a numeric
 65→ * `code` together with a `message` or a `data` field — the shape both the
 66→ * bridge and Core write. A raw resource that happens to be JSON without any
 67→ * of that is left as bytes.
 68→ */
 69→function parseEnvelope(bytes) {
 70→  if (bytes.length === 0) return null;
 71→  let parsed;
 72→  try {
 73→    parsed = JSON.parse(bytes.toString("utf8"));
 74→  } catch {
 75→    return null;
 76→  }
 77→  if (!parsed || typeof parsed !== "object" || typeof parsed.code !== "number") return null;
 78→  return typeof parsed.message === "string" || (parsed.data && typeof parsed.data === "object") ? parsed : null;
 79→}
 80→
 81→/**
 82→ * @param {object} args
 83→ * @param {string} args.skillId
 84→ * @param {string} args.path        resource path inside the skill
 85→ * @param {string} args.bridgeBase  skill-bridge base, e.g. `…/skill-bridge/v3/skill`
 86→ * @param {typeof fetch} [args.fetcher]  HTTP implementation; defaults to globalThis.fetch
 87→ * @returns {Promise<Buffer>} the resource's raw bytes (empty Buffer for an empty resource)
 88→ */
 89→export async function fetchResource({ skillId, path, bridgeBase, fetcher } = {}) {
 90→  if (!skillId) throw new Error("fetchResource: skillId is required");
 91→  if (!path) throw new Error("fetchResource: path is required");
 92→  if (!bridgeBase) throw new Error("fetchResource: bridgeBase is required");
 93→  const doFetch = fetcher ?? globalThis.fetch;
 94→
 95→  const url = `${String(bridgeBase).replace(/\/+$/, "")}/${DOWNLOAD_SUBPATH}`;
 96→  const res = await doFetch(url, {
 97→    method: "POST",
 98→    headers: { "content-type": "application/json" },
 99→    body: JSON.stringify({ skill_id: skillId, path }),
100→  });
101→
102→  const bytes = await readBytes(res);
103→  const envelope = parseEnvelope(bytes);
104→
105→  if (envelope) {
106→    if (envelope.code !== 0) {
107→      throw new Error(envelope.message ?? `fetchResource: bridge answered code ${envelope.code}`);
108→    }
109→    const data = envelope.data ?? {};
110→    const content = data.content;
111→    if (typeof content !== "string") {
112→      // code 0 but no usable content: the field is missing or the wrong type.
113→      throw new Error(envelope.message ?? "fetchResource: bridge answered code 0 without a string content");
114→    }
115→    return Buffer.from(content, data.encoding === "base64" ? "base64" : "utf8");
116→  }
117→
118→  // No envelope and no 2xx: a transport-level failure whose body is not the
119→  // bridge's own error shape (e.g. an opaque upstream error passed through).
120→  if (res && typeof res === "object" && res.ok === false) {
121→    throw new Error(`fetchResource: HTTP ${res.status ?? "?"} from ${url}`);
122→  }
123→  return bytes;
124→}
125→

freshness.description:
Filter search results by time range. Supports d[N], m[N], and y[N] for the last N calendar days, months, and years:
- d[N]: N is an integer from 1 to 30;
- m[N]: N is an integer from 1 to 12;
- y[N]: N is an integer from 1 to 5.

N may be omitted and defaults to 1. The current partial calendar unit counts as 1. For example, d1 means today, m1 means the current month to date, and y1 means the current year to date. Omit this parameter to disable time filtering.

